// ========== 寄生组合式继承（ES5 最优方案） ==========
function inheritPrototype(Child, Parent) {
  const proto = Object.create(Parent.prototype); // 创建一个以父原型为原型的新对象
  proto.constructor = Child;                       // 修正 constructor 指向
  Child.prototype = proto;                         // 赋给子类 prototype
}

function Parent(name) {
  this.name = name;
  this.colors = ['red', 'blue']; // 引用类型实例属性
}
Parent.prototype.sayName = function () {
  console.log(this.name);
};

function Child(name, age) {
  Parent.call(this, name); // 借用父构造函数，每个实例独立副本
  this.age = age;
}
inheritPrototype(Child, Parent);
Child.prototype.sayAge = function () {
  console.log(this.age);
};

// 验证：实例属性独立，方法共享
const c1 = new Child('Alice', 10);
c1.colors.push('green');
const c2 = new Child('Bob', 20);
console.log(c2.colors); // ['red', 'blue'] — 不受 c1 影响
c2.sayName();             // 'Bob'

// ========== 手写 new ==========
function myNew(Constructor, ...args) {
  // 1. 创建空对象并链接原型
  const obj = Object.create(Constructor.prototype);
  // 2. 执行构造函数
  const result = Constructor.apply(obj, args);
  // 3. 判断返回值：构造函数返回对象则用该对象，否则用 obj
  return (result !== null && typeof result === 'object') || typeof result === 'function'
    ? result
    : obj;
}

// ========== 手写 instanceof ==========
function myInstanceof(left, right) {
  if (typeof right !== 'function') throw new TypeError('right must be a function');
  let proto = Object.getPrototypeOf(left);
  while (proto !== null) {
    if (proto === right.prototype) return true;
    proto = Object.getPrototypeOf(proto);
  }
  return false;
}

// ========== class 继承（ES6+ 首选） ==========
class Animal {
  constructor(name) { this.name = name; }
  speak() { console.log(this.name + ' speaks'); }
}

class Dog extends Animal {
  constructor(name, breed) {
    super(name); // 必须在 this 之前调用，初始化父类属性并链接原型
    this.breed = breed;
  }
  bark() { console.log('Woof!'); }
}

const dog = new Dog('Rex', 'Husky');
dog.speak(); // Rex speaks
dog.bark();  // Woof!
console.log(dog instanceof Dog);    // true
console.log(dog instanceof Animal); // true
